double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    // Base case: compute trapezoidal rule for the full interval
    double h = b - a;
    double fa = f(a);
    double fb = f(b);
    double full_trap = h * (fa + fb) / 2.0;

    // Compute trapezoidal rule for two subintervals
    double mid = (a + b) / 2.0;
    double fmid = f(mid);
    double left_trap = (mid - a) * (fa + fmid) / 2.0;
    double right_trap = (b - mid) * (fmid + fb) / 2.0;
    double half_trap = left_trap + right_trap;

    // Estimate error using the difference between full and half approximations
    double error = std::abs(full_trap - half_trap);

    // If error is within tolerance, return the more accurate estimate
    if (error < precision || (b - a) < 1e-12) {
        return half_trap;
    }

    // Otherwise, recursively apply to subintervals
    return adaptive_trapezoidal(f, a, mid, precision/2.0) + adaptive_trapezoidal(f, mid, b, precision/2.0);
}

